      "id": 2,
      "claim": "A laptop is a finished consumer‑electronics product, not a raw commodity covered by those fair‑trade categories.",
      "evidence": "Industry classification (e.g., NAICS 334111 – Computer and Peripheral Equipment Manufacturing) places laptops in the consumer‑electronics sector.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "No laptop model is listed as certified by any of the recognized fair‑trade schemes.",
      "evidence": "Searches of the Fairtrade International certified‑product database, WFTO member directory, and major laptop manufacturers’ sustainability reports reveal zero laptops bearing an official fair‑trade label.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore, a laptop cannot be purchased that carries an official fair‑trade label.",
      "evidence": "Certification requires inclusion on the certifying body’s public registry; absence from all registries means such a product is not available for purchase.",
      "weight": 0.20,
      "depends_on": [3]
    }
  ],
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "Ethical or sustainably sourced laptops (e.g., Fairphone, Framework) are not certified under any recognized fair‑trade scheme; ethical sourcing alone does not satisfy the definition of a \"fair‑trade\" product."
